package com.example.ayni.emergency.model;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="emergency_alerts")public class EmergencyAlert{@Id private UUID id;private String type;private String source;private String title;private String description;private String zone;@Column(name="issued_at")private Instant issuedAt;@Column(name="expires_at")private Instant expiresAt;private String status;protected EmergencyAlert(){}public UUID getId(){return id;}public String getTitle(){return title;}public String getDescription(){return description;}public String getZone(){return zone;}public String getStatus(){return status;}}
